/* ZILO script.js - loads its own libraries, so no CodePen Settings links are needed */
const LOGO='data:image/webp;base64,';
document.querySelectorAll('.logo').forEach(i=>i.src=LOGO);
const LOGO_MARK='data:image/webp;base64,';
/* ===== OPENING VOICE =====
   1. Upload your recording (mp3) somewhere public and paste its link below.
   2. Set the second each word STARTS in your recording (Design, Try, Tailor).
   3. SPLASH_END = the second the logo should zoom away (after your voice finishes).
   With no link, the phone's built-in voice is used (slower, and some phones keep it silent). */
const SPLASH_AUDIO='';
const SPLASH_CUES=[1.3,2.7,4.1];
const SPLASH_END=5.6;
(function splash(){
  const sp=document.getElementById('splash');if(!sp)return;
  document.getElementById('spLogo').src=LOGO_MARK;
  const D="M46 18 L31 27 Q26 30 27 37 L31 70 Q33 80 38 84 L62 84 Q67 80 69 70 L73 37 Q74 30 69 27 L54 18",STAND='M50 84 V110 M36 112 H64';
  const ART=[
    `<svg viewBox="0 0 100 120"><path class="ol blue" d="${D}"/><path class="ol blue" d="${STAND}"/><circle class="ol" cx="50" cy="10" r="4"/><path class="cons" d="M27 45 H73 M31 62 H69 M50 20 V84"/><g class="pen"><path d="M72 16 l14 -8 l3 5 l-14 8 z" fill="#f59e0b"/></g></svg>`,
    `<svg viewBox="0 0 100 120"><path class="fillcyc" d="${D} Z"/><path class="ol" d="${STAND}" style="animation:none;stroke-dashoffset:0"/><circle cx="50" cy="10" r="4" fill="#0b1220"/><ellipse class="scan" cx="50" cy="26" rx="30" ry="5"/></svg>`,
    `<svg viewBox="0 0 100 120"><path d="${D} Z" fill="#1e3a8a" stroke="#0b1220" stroke-width="2" stroke-linejoin="round"/><path d="${STAND}" stroke="#0b1220" stroke-width="2" fill="none"/><circle cx="50" cy="10" r="4" fill="#0b1220"/><path class="stitch" d="M50 22 V82"/><path class="tapeB" d="M36 22 L64 68"/><path class="tapeT" d="M36 22 L64 68"/></svg>`];
  const words=[...sp.querySelectorAll('.spWords span')],stage=document.getElementById('spStage'),hint=document.getElementById('spHint'),W=['Design','Try','Tailor'];
  let started=false,done=false,t0=0,audio=null,tick=null,tried=false;
  const say=t=>{try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.rate=.75;u.pitch=1.05;const v=speechSynthesis.getVoices().find(v=>/female|zira|samantha|google uk english female/i.test(v.name));if(v)u.voice=v;speechSynthesis.speak(u)}catch(e){}};
  const show=(i,talk)=>{words.forEach((w,j)=>w.classList.toggle('hot',j===i));stage.innerHTML=ART[i];if(talk)say(W[i])};
  const finish=()=>{if(done)return;done=true;clearInterval(tick);if(audio)audio.pause();sp.classList.add('out');document.body.classList.add('spOut');setTimeout(()=>sp.remove(),700)};
  function begin(){
    if(started)return;started=true;if(hint)hint.classList.remove('on');t0=Date.now();
    SPLASH_CUES.forEach((c,i)=>setTimeout(()=>show(i,!audio),c*1000));
    const end=Math.max(SPLASH_END,audio&&isFinite(audio.duration)?audio.duration+.6:0);
    tick=setInterval(()=>{if(Date.now()-t0>=end*1000&&window.__zReady)finish()},100);
  }
  function tryPlay(){
    if(tried||started)return;tried=true;
    audio.play().then(begin).catch(()=>{
      if(hint)hint.classList.add('on');
      const unlock=()=>{audio.play().then(begin).catch(begin)};
      ['pointerdown','keydown','touchstart'].forEach(ev=>window.addEventListener(ev,unlock,{once:true,passive:true}));
    });
  }
  if(SPLASH_AUDIO){
    audio=new Audio(SPLASH_AUDIO);audio.preload='auto';
    audio.addEventListener('canplaythrough',tryPlay,{once:true});
    audio.addEventListener('error',()=>{audio=null;begin()},{once:true});
    setTimeout(tryPlay,2500);
  }else begin();
  sp.addEventListener('click',()=>{if(started&&Date.now()-t0>1500&&window.__zReady)finish()});
})();

