  try{const u=new SpeechSynthesisUtterance(line);const v=speechSynthesis.getVoices().find(v=>/female|zira|samantha|google uk english female/i.test(v.name));if(v)u.voice=v;u.pitch=1.1;speechSynthesis.speak(u)}catch(e){}
