$('#lGo').onclick=async()=>{
  const email=$('#lEmail').value.trim(),password=$('#lPass').value,msg=$('#aMsg');
  if(!sb){msg.textContent='Login is not available: the Supabase script did not load.';return}
  if(!email||password.length<6){msg.textContent='Enter an email and a password of 6 or more characters.';return}
  msg.textContent='Please wait…';
  if(signUp){
    const meta={name:$('#lName').value||'Guest',g:segVal('lGender')};
    const {data,error}=await sb.auth.signUp({email,password,options:{data:meta}});
    if(error){msg.textContent=error.message;return}
    if(!data.session){msg.textContent='Check your email to confirm your account, then sign in.';return}
    msg.textContent='';enter(data.user,false);
  }else{
    const {data,error}=await sb.auth.signInWithPassword({email,password});
    if(error){msg.textContent=error.message;return}
    msg.textContent='';enter(data.user,true);
  }
};
