/* ---------- Real 3D models (.glb) registry ---------- */
const MODELS={f:{},m:{}};
const GLB={};
function loadGLB(url,cb){
  const e=GLB[url];
  if(e){if(e.state==='ready')cb();else if(e.state==='loading')e.cbs.push(cb);return}
  GLB[url]={state:'loading',cbs:[cb]};
  if(!THREE.GLTFLoader){GLB[url].state='error';return}
  new THREE.GLTFLoader().load(url,g=>{GLB[url].scene=g.scene;GLB[url].state='ready';GLB[url].cbs.forEach(f=>f())},undefined,()=>{GLB[url].state='error'});
}

